def brackets_ok(s: str) -> bool:
    opener = {")": "(", "]": "[", "}": "{"}
    stack = []                      # brackets still open, the latest on top
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in opener:
            if not stack or stack.pop() != opener[ch]:
                return False        # nothing open, or the wrong kind
    return not stack                # anything left was never closed

perf.naive:
def brackets_ok(s: str) -> bool:
    s = ''.join(ch for ch in s if ch in '()[]{}')
    while True:
        shorter = s.replace('()', '').replace('[]', '').replace('{}', '')
        if shorter == s:
            return s == ''
        s = shorter
